"""
Inventory Manager -- handles three pools:
  * Items     : hand-made JSON files in items/*.json  (scanned, git-synced)
  * Artifacts : generated by ArtifactGenerator, stored in SQLite — granted
                as mission rewards or bought from the shop
  * Shop stock: the artifacts currently for sale (SQLite shop_stock table)
"""
import json
import random
import sqlite3
from pathlib import Path
from typing import List, Dict, Any, Optional
from dataclasses import dataclass

from athas.artifact_generator import (
    ArtifactGenerator, RARITIES, SACRIFICE_PER_FUSION,
)


@dataclass
class InventoryItem:
    uid: str
    name: str
    category: str          # "item" | "artifact"
    item_type: str
    description: str
    story: str
    rarity: str            # Common, Uncommon, Rare, Epic, Legendary, Mythic
    image_path: str        # absolute or relative to rp root
    stats: Dict[str, Any]
    count: int = 1
    level: int = 1
    source_file: str = ""  # for JSON items
    source: str = ""       # artifact origin: "mission" | "shop"


_ARTIFACTS_SQL = """
    CREATE TABLE IF NOT EXISTS artifacts (
        id          INTEGER PRIMARY KEY AUTOINCREMENT,
        name        TEXT NOT NULL,
        item_type   TEXT NOT NULL,
        rarity      TEXT NOT NULL,
        level       INTEGER DEFAULT 1,
        stats       TEXT DEFAULT '{}',
        source      TEXT DEFAULT 'mission',
        description TEXT DEFAULT '',
        story       TEXT DEFAULT '',
        created_at  TEXT DEFAULT CURRENT_TIMESTAMP
    )
"""

_SHOP_STOCK_SQL = """
    CREATE TABLE IF NOT EXISTS shop_stock (
        id          INTEGER PRIMARY KEY AUTOINCREMENT,
        name        TEXT NOT NULL,
        item_type   TEXT NOT NULL,
        rarity      TEXT NOT NULL,
        level       INTEGER DEFAULT 1,
        stats       TEXT DEFAULT '{}',
        price       INTEGER NOT NULL,
        description TEXT DEFAULT '',
        story       TEXT DEFAULT '',
        created_at  TEXT DEFAULT CURRENT_TIMESTAMP
    )
"""


class InventoryManager:
    """Owns the artifact database: earned artifacts plus the shop's stock."""

    SHOP_STOCK_SIZE = 6
    PACKAGE_SIZE = 10      # artifacts in the shop's bulk common package
    PACKAGE_PRICE = 400    # gold for the package

    def __init__(
        self,
        items_dir: str,
        library_dir: str,
        cache_dir: str,
        rp_root: str,
    ):
        self.items_dir = Path(items_dir)
        self.library_dir = Path(library_dir)
        self.cache_dir = Path(cache_dir)
        self.rp_root = Path(rp_root)

        self.items_dir.mkdir(parents=True, exist_ok=True)
        self.cache_dir.mkdir(parents=True, exist_ok=True)

        self.generator = ArtifactGenerator(library_dir)
        self.db_path = self.cache_dir / "inventory.db"
        self._init_db()

    # --- Database ---
    def _init_db(self):
        with sqlite3.connect(str(self.db_path)) as conn:
            conn.execute(_ARTIFACTS_SQL)
            # --- migrate databases from earlier artifact systems ---
            cols = {row[1] for row in conn.execute("PRAGMA table_info(artifacts)")}
            legacy = False
            if "source" not in cols:
                conn.execute("ALTER TABLE artifacts ADD COLUMN source TEXT DEFAULT 'legacy'")
                legacy = True
            if "description" not in cols:
                conn.execute("ALTER TABLE artifacts ADD COLUMN description TEXT DEFAULT ''")
            if "story" not in cols:
                conn.execute("ALTER TABLE artifacts ADD COLUMN story TEXT DEFAULT ''")
            if legacy:
                # Old rows were blind auto-seeds built from empty word lists
                # (twenty "Unknown Relic"s) — the new system starts clean.
                conn.execute("DELETE FROM artifacts WHERE source = 'legacy'")
            if "adjective" in cols:
                # The adjective-based generator kept a dedicated column —
                # rebuild the table without it, keeping the row ids so
                # mission credits still point at the same artifacts.
                conn.execute("ALTER TABLE artifacts RENAME TO artifacts_old")
                conn.execute(_ARTIFACTS_SQL)
                conn.execute("""
                    INSERT INTO artifacts
                        (id, name, item_type, rarity, level, stats, source, description, story, created_at)
                    SELECT id, name, item_type, rarity, level, stats, source, description, story, created_at
                    FROM artifacts_old
                """)
                conn.execute("DROP TABLE artifacts_old")
            conn.execute(_SHOP_STOCK_SQL)
            shop_cols = {row[1] for row in conn.execute("PRAGMA table_info(shop_stock)")}
            if "adjective" in shop_cols:
                # Same rebuild for the shop shelves.
                conn.execute("ALTER TABLE shop_stock RENAME TO shop_stock_old")
                conn.execute(_SHOP_STOCK_SQL)
                conn.execute("""
                    INSERT INTO shop_stock
                        (id, name, item_type, rarity, level, stats, price, description, story, created_at)
                    SELECT id, name, item_type, rarity, level, stats, price, description, story, created_at
                    FROM shop_stock_old
                """)
                conn.execute("DROP TABLE shop_stock_old")
            conn.commit()

    @staticmethod
    def _parse_stats(raw: Any) -> Dict[str, Any]:
        try:
            data = json.loads(raw or "{}")
            return data if isinstance(data, dict) else {}
        except Exception:
            return {}

    # --- Artifacts (generate / read / delete) ---
    def _insert_artifact(self, conn, payload: Dict[str, Any]) -> int:
        cur = conn.execute("""
            INSERT INTO artifacts
                (name, item_type, rarity, level, stats, source, description, story)
            VALUES
                (:name, :item_type, :rarity, :level, :stats, :source, :description, :story)
        """, payload)
        return int(cur.lastrowid or 0)

    def _row_to_item(self, row) -> InventoryItem:
        return InventoryItem(
            uid=f"artifact:{row['id']}",
            name=row["name"],
            category="artifact",
            item_type=row["item_type"],
            description=row["description"] or f"A {row['rarity']} {row['item_type']}.",
            story=row["story"] or "",
            rarity=row["rarity"],
            image_path="",
            stats=self._parse_stats(row["stats"]),
            count=1,
            level=row["level"],
            source_file=str(self.db_path),
            source=row["source"] or "",
        )

    def generate_artifacts(self, count: int = 1, rarity: Optional[str] = None,
                           difficulty: Optional[str] = None, level: int = 1,
                           source: str = "mission") -> List[InventoryItem]:
        """Roll `count` new artifacts, store them, and return them as items."""
        items: List[InventoryItem] = []
        with sqlite3.connect(str(self.db_path)) as conn:
            for _ in range(max(0, count)):
                a = self.generator.generate(rarity=rarity, difficulty=difficulty, level=level)
                payload = {
                    "name": a["name"],
                    "item_type": a["item_type"],
                    "rarity": a["rarity"],
                    "level": a["level"],
                    "stats": json.dumps(a["stats"]),
                    "source": source,
                    "description": a["description"],
                    "story": a["story"],
                }
                new_id = self._insert_artifact(conn, payload)
                items.append(InventoryItem(
                    uid=f"artifact:{new_id}",
                    name=a["name"],
                    category="artifact",
                    item_type=a["item_type"],
                    description=a["description"],
                    story=a["story"],
                    rarity=a["rarity"],
                    image_path="",
                    stats=a["stats"],
                    count=1,
                    level=a["level"],
                    source_file=str(self.db_path),
                    source=source,
                ))
            conn.commit()
        return items

    def delete_artifacts(self, ids: List[Any]):
        """Remove artifacts by id — used to revoke mission rewards."""
        clean: List[int] = []
        for value in ids or []:
            try:
                clean.append(int(value))
            except (TypeError, ValueError):
                continue
        if not clean:
            return
        with sqlite3.connect(str(self.db_path)) as conn:
            placeholders = ",".join("?" * len(clean))
            conn.execute(f"DELETE FROM artifacts WHERE id IN ({placeholders})", clean)
            conn.commit()

    # --- Items (JSON scan) ---
    def scan_items(self) -> List[InventoryItem]:
        self.items_dir.mkdir(parents=True, exist_ok=True)
        items: List[InventoryItem] = []
        for file_path in self.items_dir.iterdir():
            if not file_path.is_file() or file_path.suffix.lower() != ".json":
                continue
            try:
                data = json.loads(file_path.read_text(encoding="utf-8"))
            except Exception:
                continue
            img = data.get("image", "")
            img_path = self._resolve_image(img, file_path.parent)
            items.append(InventoryItem(
                uid=f"item:{file_path.stem}",
                name=data.get("name", file_path.stem.replace("_", " ").title()),
                category="item",
                item_type=data.get("type", "Misc"),
                description=data.get("description", ""),
                story=data.get("story", ""),
                rarity=data.get("rarity", "Common"),
                image_path=img_path,
                stats=data.get("stats", {}),
                count=data.get("count", 1),
                level=data.get("level", 1),
                source_file=str(file_path),
            ))
        return items

    def _resolve_image(self, img: str, fallback_dir: Path) -> str:
        if not img:
            return ""
        p = Path(img)
        if p.is_absolute() and p.exists():
            return str(p)
        cand = fallback_dir / img
        if cand.exists():
            return str(cand)
        cand2 = self.rp_root / "icons" / img
        if cand2.exists():
            return str(cand2)
        return str(cand)

    # --- Artifacts (DB read) ---
    def get_artifacts(self) -> List[InventoryItem]:
        items: List[InventoryItem] = []
        with sqlite3.connect(str(self.db_path)) as conn:
            conn.row_factory = sqlite3.Row
            for row in conn.execute("SELECT * FROM artifacts"):
                items.append(self._row_to_item(row))
        # Highest rarity first, then level, then name.
        rank = {r: i for i, r in enumerate(RARITIES)}
        items.sort(key=lambda it: (-rank.get(it.rarity, -1), -it.level, it.name))
        return items

    def all_inventory(self) -> List[InventoryItem]:
        return self.scan_items() + self.get_artifacts()

    # --- Removal ---
    def delete_artifact(self, uid: str):
        if not uid.startswith("artifact:"):
            return
        pk = uid.split(":", 1)[1]
        with sqlite3.connect(str(self.db_path)) as conn:
            conn.execute("DELETE FROM artifacts WHERE id = ?", (pk,))
            conn.commit()

    # --- Shop stock ---
    def get_shop_stock(self) -> List[Dict[str, Any]]:
        with sqlite3.connect(str(self.db_path)) as conn:
            conn.row_factory = sqlite3.Row
            rows = conn.execute("SELECT * FROM shop_stock ORDER BY price ASC").fetchall()
        return [
            {
                "id": row["id"],
                "name": row["name"],
                "item_type": row["item_type"],
                "rarity": row["rarity"],
                "level": row["level"],
                "stats": self._parse_stats(row["stats"]),
                "price": row["price"],
                "description": row["description"] or "",
                "story": row["story"] or "",
            }
            for row in rows
        ]

    def restock_shop(self, player_level: int = 1, count: Optional[int] = None):
        """Reroll the shop shelves with fresh generated artifacts."""
        count = self.SHOP_STOCK_SIZE if count is None else max(0, int(count))
        with sqlite3.connect(str(self.db_path)) as conn:
            conn.execute("DELETE FROM shop_stock")
            for _ in range(count):
                level = random.randint(1, max(1, int(player_level)))
                a = self.generator.generate(rarity=self.generator.roll_shop_rarity(), level=level)
                conn.execute("""
                    INSERT INTO shop_stock
                        (name, item_type, rarity, level, stats, price, description, story)
                    VALUES
                        (:name, :item_type, :rarity, :level, :stats, :price, :description, :story)
                """, {
                    **a,
                    "stats": json.dumps(a["stats"]),
                    "price": self.generator.price(a["rarity"], a["level"]),
                })
            conn.commit()

    def buy_from_shop(self, stock_id: Any) -> Optional[InventoryItem]:
        """Move an artifact from the shop shelves into the inventory."""
        try:
            stock_id = int(stock_id)
        except (TypeError, ValueError):
            return None
        with sqlite3.connect(str(self.db_path)) as conn:
            conn.row_factory = sqlite3.Row
            row = conn.execute(
                "SELECT * FROM shop_stock WHERE id = ?", (stock_id,)
            ).fetchone()
            if row is None:
                return None
            conn.execute("DELETE FROM shop_stock WHERE id = ?", (stock_id,))
            payload = {
                "name": row["name"],
                "item_type": row["item_type"],
                "rarity": row["rarity"],
                "level": row["level"],
                "stats": row["stats"],
                "source": "shop",
                "description": row["description"] or "",
                "story": row["story"] or "",
            }
            new_id = self._insert_artifact(conn, payload)
            conn.commit()
        return InventoryItem(
            uid=f"artifact:{new_id}",
            name=row["name"],
            category="artifact",
            item_type=row["item_type"],
            description=row["description"] or "",
            story=row["story"] or "",
            rarity=row["rarity"],
            image_path="",
            stats=self._parse_stats(row["stats"]),
            count=1,
            level=row["level"],
            source_file=str(self.db_path),
            source="shop",
        )

    def buy_common_package(self, player_level: int = 1) -> List[InventoryItem]:
        """The shop's bulk deal: PACKAGE_SIZE common artifacts at once."""
        items: List[InventoryItem] = []
        for _ in range(self.PACKAGE_SIZE):
            level = random.randint(1, max(1, int(player_level)))
            items.extend(self.generate_artifacts(
                count=1, rarity="Common", level=level, source="shop",
            ))
        return items

    def sacrifice_artifacts(self, ids: List[Any]) -> Optional[InventoryItem]:
        """Fuse SACRIFICE_PER_FUSION artifacts of one rarity into a single
        artifact of the next rarity with fresh random stats.

        Returns the forged artifact, or None when the sacrifice is invalid
        (wrong count, missing rows, mixed rarities, or Mythic input)."""
        clean: List[int] = []
        for value in ids or []:
            try:
                clean.append(int(value))
            except (TypeError, ValueError):
                return None
        if len(clean) != SACRIFICE_PER_FUSION:
            return None
        placeholders = ",".join("?" * len(clean))
        with sqlite3.connect(str(self.db_path)) as conn:
            conn.row_factory = sqlite3.Row
            rows = conn.execute(
                f"SELECT * FROM artifacts WHERE id IN ({placeholders})", clean
            ).fetchall()
            if len(rows) != SACRIFICE_PER_FUSION:
                return None
            rarities = {row["rarity"] for row in rows}
            if len(rarities) != 1:
                return None
            rarity = rarities.pop()
            if rarity not in RARITIES or rarity == RARITIES[-1]:
                return None  # Mythic has no higher rank
            forge_level = max(1, max(int(row["level"] or 1) for row in rows))
            conn.execute(f"DELETE FROM artifacts WHERE id IN ({placeholders})", clean)
            conn.commit()
        next_rarity = RARITIES[RARITIES.index(rarity) + 1]
        forged = self.generate_artifacts(
            count=1, rarity=next_rarity, level=forge_level, source="forge",
        )
        return forged[0] if forged else None
